#!/bin/bash
# lawbattery.sh <corpus> <mode> <test>: every single law switch of passes 133 and 137 (+139 roads, v137 refinements) on one row
source $(dirname $0)/env.sh
S="R11U133_LHSCLONE_OFF R11U133_HPMID_OFF R11U133_TRAILIDX_OFF R11U133_PATQUAL_OFF R11U133_UNKFILE_OFF R11U137_ELABCLONE_OFF R11U137_ELABCLONE_PKG_OFF R11U137_PATD_OFF R11U137_EMPTYCONN_OFF R11U137_UNSIGNEDSPAN_OFF R11U137_CALLSPAN_OFF R11U137_REPLTSNAME_OFF R11U137_PUREVIRTSPAN_OFF R11U137_TAGGEDSPAN_OFF R11U137_DEFNETTP_OFF R11U137_ALIASFILE_OFF R11U137_SCOPEDARRTD_OFF R11U137_PATHBASE_OFF R11U139_CA_OFF R11U139_NDA_OFF R11U139_CLK_OFF R11U139_PORT_OFF R11V137_DEFWIRE_OFF R11V137_PVQUAL_OFF"
args="ON= X133=R11U133_OFF X137=R11U137_OFF,R11U139_OFF,R11V137_OFF"
for s in $S; do args="$args ${s%_OFF}=$s"; done
python3 $(dirname $0)/rowsw.py $1 $2 $3 $args
